Object.assign(hc,{venueType:'all',pairType:'perp-perp',units:'pct',costs:true,limit:50,minFunding:'',minSpread:'',minVsAvg:'',minVolume:'',minOi:'',minLeverage:'',minNet:'',sameInterval:false,paidPositive:false,oneAsset:false,columns:['spread','average','fees','net','trend','risk'],readJobs:{},presets:[]});
try{hc.presets=JSON.parse(localStorage.getItem('neutralbasis.presets')||'[]')}catch{}
const wideKinds=()=>Object.fromEntries((viewData().registry||[]).map(r=>[r.id,r.kind]));
const wpct=x=>x==null?'—':hc.units==='bp'?(x*10000).toFixed(3)+' bp':pct(x);
const wrate=x=>x==null?'—':hc.units==='bp'?(x*hc.period*10000).toFixed(3)+' bp':rate(x);
const intervalLabel=x=>x==null?'?':x===0?'spot':(x/3600)+'h';
const keyFor=p=>[p.asset,p.long,p.short,p.pair_type||'perp-perp'].join(':');
const wideFilterFields=['query','venue','venueType','pairType','units','costs','period','size','minFunding','minSpread','minVsAvg','minVolume','minOi','minLeverage','minNet','sameInterval','paidPositive','oneAsset','sort'];
function savePreset(){const input=document.getElementById('preset-name'),title=input.value.trim();if(!title)return;const data=Object.fromEntries(wideFilterFields.map(k=>[k,hc[k]]));hc.presets=[...hc.presets.filter(p=>p.name!==title),{name:title,tab,data}].slice(-6);localStorage.setItem('neutralbasis.presets',JSON.stringify(hc.presets));notice='Filtre kaydedildi.';render()}
function applyPreset(i){const p=hc.presets[i];Object.assign(hc,p.data);navigate(p.tab)}
function resetFilters(){for(const k of ['minFunding','minSpread','minVsAvg','minVolume','minOi','minLeverage','minNet','query'])hc[k]='';Object.assign(hc,{venue:'all',venueType:'all',sameInterval:false,paidPositive:false,oneAsset:false,favorites:false,positive:false,above:false,limit:50});document.getElementById('global-search').value='';render()}
async function shareFilters(){const params=new URLSearchParams();for(const k of wideFilterFields)params.set(k,String(hc[k]));const link=location.origin+location.pathname+'#'+tab+'?'+params;try{await navigator.clipboard.writeText(link);notice='Filtre bağlantısı panoya kopyalandı.'}catch{notice=link}render()}
function wideParseLink(){const params=new URLSearchParams(location.hash.split('?')[1]||'');if(!params.size)return;for(const k of wideFilterFields)if(params.has(k)){const val=params.get(k);hc[k]=typeof hc[k]==='boolean'?val==='true':typeof hc[k]==='number'?Number(val):val}tab=location.hash.slice(1).split('?')[0]||'funding'}
wideParseLink();window.addEventListener('hashchange',wideParseLink);
const btLinkParams=new URLSearchParams(location.hash.split('?')[1]||'');if(btLinkParams.has('asset')){for(const k of ['long_kind','start_iso','end_iso'])if(btLinkParams.has(k))hc.btForm[k]=btLinkParams.get(k);if([1,7,30,90].includes(Number(btLinkParams.get('days'))))hc.days=Number(btLinkParams.get('days'));if(btLinkParams.has('slippage_bps'))hc.btForm.slippage_bps=Number(btLinkParams.get('slippage_bps'));if(btLinkParams.has('price'))hc.btForm.include_price=btLinkParams.get('price')==='true'}
async function shareBacktest(){const p=new URLSearchParams();for(const k of ['asset','long','short','size','long_kind','slippage_bps','start_iso','end_iso'])if(hc.btForm[k]!=null)p.set(k,String(hc.btForm[k]));p.set('days',hc.days);p.set('price',hc.btForm.include_price);const link=location.origin+location.pathname+'#backtest?'+p;try{await navigator.clipboard.writeText(link);notice='Backtest kurulum bağlantısı kopyalandı.'}catch{notice=link}render()}
const originalWideBacktest=backtestScreen;backtestScreen=function(){return originalWideBacktest().replace('<h2>Sonuç</h2>','<h2>Sonuç</h2><button onclick="shareBacktest()">Kurulum bağlantısı ↗</button>')};
function advancedFilters(){const fields=[['minFunding','Asgari funding · '+periodLabel()+(hc.units==='bp'?' / bp':' / %')],['minSpread','Asgari fiyat farkı · bp'],['minVsAvg','7g ortalamasından uzaklık · bp'],['minVolume','Her bacak 24s hacim · USD'],['minOi','Her perp bacak OI · USD'],['minLeverage','Her bacak azami kaldıraç ≥'],['minNet','Ücret sonrası gösterge ≥ USD']];return `<div class="wide-filter-panel ${hc.help?'open':''}"><form id="wide-filters"><div class="filter-grid">${fields.map(([k,label])=>`<label>${label}<input type="number" name="${k}" value="${esc(hc[k])}" step="any" placeholder="Sınır yok"></label>`).join('')}</div><div class="filters"><label><input type="checkbox" name="sameInterval" ${hc.sameInterval?'checked':''}> Aynı ödeme aralığı</label><label><input type="checkbox" name="paidPositive" ${hc.paidPositive?'checked':''}> Gerçekleşmiş 7g funding pozitif</label><label><input type="checkbox" name="oneAsset" ${hc.oneAsset?'checked':''}> Varlık başına bir çift</label><button class="primary">Filtreleri uygula</button><button type="button" onclick="resetFilters()">Sıfırla</button></div><p class="tooltip">Bilinmeyen hacim/OI/geçmiş, bu alanlarda sınır seçildiğinde filtreyi geçmez. Hacim ve OI yalnızca kaynakta USD değeri doğrulanmışsa gösterilir.</p></form></div>`}
commonFilters=function(price=false){const cov=viewData().coverage||{};return `<div class="toolbar"><div class="toolbar-left"><button onclick="hcSet('help',!hc.help)">☷ Filtreler ${hc.help?'▴':'▾'}</button><span class="screener-count">${cov.available||0} erişilebilir / ${cov.total||63} platform</span><div class="segmented">${['all','DEX','CEX'].map(k=>`<button class="${hc.venueType===k?'active':''}" onclick="hcSet('venueType','${k}')">${k==='all'?'Tümü':k}</button>`).join('')}</div><button onclick="hcSet('favorites',!hc.favorites)" class="${hc.favorites?'active':''}">★ Favoriler</button></div><div class="rate-control">${periods()}<div class="segmented"><button class="${hc.units==='pct'?'active':''}" onclick="hcSet('units','pct')">%</button><button class="${hc.units==='bp'?'active':''}" onclick="hcSet('units','bp')">bp</button></div><select aria-label="Borsa filtresi" onchange="hcSet('venue',this.value)"><option value="all">Tüm borsalar</option>${hcVenues.map(v=>`<option value="${v}" ${hc.venue===v?'selected':''}>${esc(name(v))}</option>`).join('')}</select></div></div>${advancedFilters()}<div class="filters"><div class="segmented"><button class="${hc.pairType==='perp-perp'?'active':''}" onclick="hcSet('pairType','perp-perp')">Perp + perp</button>${price?`<button class="${hc.pairType==='spot-perp'?'active':''}" onclick="hcSet('pairType','spot-perp')">Spot + perp</button><button class="${hc.pairType==='all'?'active':''}" onclick="hcSet('pairType','all')">İkisi</button>`:''}</div><label class="tooltip"><input type="checkbox" ${hc.costs?'checked':''} onchange="hcSet('costs',this.checked)"> Göstergeye taker ücretlerini dahil et</label><button onclick="shareFilters()">Bağlantıyı kopyala ↗</button><input id="preset-name" aria-label="Filtre kaydı adı" placeholder="Filtre kaydı adı" maxlength="40"><button onclick="savePreset()">Filtreyi kaydet</button>${hc.presets.map((p,i)=>`<button onclick="applyPreset(${i})">${esc(p.name)}</button>`).join('')}</div>`};
netEstimate=function(p,price){if((hc.costs&&p.fee_roundtrip==null)||(price&&!p.history)||(!price&&p.funding==null))return null;return hc.size*((price?p.spread-p.history.mean:p.funding*state.config.horizon)-(hc.costs?p.fee_roundtrip:0))};
filteredPairs=function(price){const kinds=wideKinds();let ps=viewData().pairs.filter(p=>price?hc.pairType==='all'||p.pair_type===hc.pairType:p.pair_type==='perp-perp').map(p=>{if(price||p.funding==null||p.funding>=0)return {...p};return {...p,long:p.short,short:p.long,long_price:p.short_price,short_price:p.long_price,funding:-p.funding,spread:-p.spread,paid24:p.paid24==null?null:-p.paid24,paid7:p.paid7==null?null:-p.paid7,long_interval:p.short_interval,short_interval:p.long_interval,history:p.history?{...p.history,mean:-p.history.mean,points:p.history.points.map(x=>({...x,spread:-x.spread,long_price:x.short_price,short_price:x.long_price}))}:null}});
 ps=ps.filter(p=>(!hc.query||[p.asset,p.long,p.short,name(p.long),name(p.short)].join(' ').toLowerCase().includes(hc.query.toLowerCase()))&&(hc.venue==='all'||[p.long,p.short].includes(hc.venue))&&(hc.venueType==='all'||[p.long,p.short].every(v=>kinds[v]===hc.venueType))&&(!hc.favorites||hc.stars.has(keyFor(p)))&&(!hc.above||p.history&&p.spread>p.history.mean)&&(!hc.sameInterval||p.long_interval===p.short_interval)&&(!hc.paidPositive||p.paid7>0));
 const threshold=(key,value)=>hc[key]===''||value!=null&&Number.isFinite(value)&&value>=Number(hc[key]);
 ps=ps.filter(p=>threshold('minFunding',p.funding==null?null:p.funding*hc.period*(hc.units==='bp'?10000:100))&&threshold('minSpread',p.spread*10000)&&threshold('minVsAvg',p.history?(p.spread-p.history.mean)*10000:null)&&threshold('minVolume',p.min_volume)&&threshold('minOi',p.min_oi)&&threshold('minLeverage',p.leverage)&&threshold('minNet',netEstimate(p,price)));
 ps.sort((a,b)=>hc.sort==='asset'?a.asset.localeCompare(b.asset):hc.sort==='net'?(netEstimate(b,price)??-Infinity)-(netEstimate(a,price)??-Infinity):hc.sort==='volume'?(b.min_volume??-Infinity)-(a.min_volume??-Infinity):hc.sort==='paid7'?(b.paid7??-Infinity)-(a.paid7??-Infinity):price?b.spread-a.spread:(b.funding??-Infinity)-(a.funding??-Infinity));
 if(hc.oneAsset){const seen=new Set();ps=ps.filter(p=>{if(seen.has(p.asset))return false;seen.add(p.asset);return true})}hc.total=ps.length;return ps.slice(0,hc.limit)};
function wideStar(key){hc.stars.has(key)?hc.stars.delete(key):hc.stars.add(key);localStorage.setItem('neutralbasis.favorites',JSON.stringify([...hc.stars]));render()}
function columnToggle(id){hc.columns=hc.columns.includes(id)?hc.columns.filter(c=>c!==id):[...hc.columns,id];render()}
function wideColumns(){return `<details class="columns-control"><summary>Sütunlar ${hc.columns.length}/10</summary><div>${[['spread','Fiyat farkı'],['average','7g ortalaması'],['fees','4 emir ücretleri'],['net','Net gösterge'],['trend','Spread grafiği'],['risk','Risk durumu'],['liquidity','Hacim / OI'],['leverage','Kaldıraç'],['paid','Gerçekleşmiş funding'],['interval','Ödeme aralığı']].map(([k,l])=>`<label><input type="checkbox" ${hc.columns.includes(k)?'checked':''} onchange="columnToggle('${k}')"> ${l}</label>`).join('')}</div></details>`}
screener=function(price=false){const ps=filteredPairs(price),col=k=>hc.columns.includes(k),cov=viewData().coverage||{};return head(price?'Fiyat arbitrajı':'Funding oranları',`${cov.dex||0} DEX + ${cov.cex||0} CEX erişilebilir. ${state.config.symbols.length} seçili varlık; public piyasa verileri, bağımsız paper risk motoru.`)+`<div class="filters"><div class="segmented"><button class="${hc.view==='list'?'active':''}" onclick="hcSet('view','list')">Çift listesi</button>${!price?`<button class="${hc.view==='matrix'?'active':''}" onclick="hcSet('view','matrix')">Borsa matrisi</button>`:''}</div><span class="tooltip">${cov.adapters||0} public adaptör / ${cov.total||63} katalog kaydı. <a href="#exchanges">Kapsam ve eksikler ↗</a></span></div>`+commonFilters(price)+(!price&&hc.view==='matrix'?fundingMatrix():`<div class="toolbar"><span class="screener-count">${hc.total.toLocaleString()} çift · ilk ${ps.length}</span><div class="rate-control"><input id="pair-search" class="search" aria-label="Çift tablosunda ara" placeholder="Varlık veya borsa ara" value="${esc(hc.query)}" oninput="hcQuery(this)"><label class="inline-label">Bacak / USD<input aria-label="Gösterge bacak büyüklüğü" type="number" min="10" max="1000000" value="${hc.size}" oninput="hc.size=Number(this.value)||1000" onchange="render()"></label><select aria-label="Sıralama" onchange="hcSet('sort',this.value)">${[['funding',price?'Fiyat farkı ↓':'Funding farkı ↓'],['net','Net gösterge ↓'],['volume','24s hacim ↓'],['paid7','Gerçekleşmiş funding 7g ↓'],['asset','Varlık A–Z']].map(([v,l])=>`<option value="${v}" ${hc.sort===v?'selected':''}>${l}</option>`).join('')}</select>${wideColumns()}</div></div><div class="table-wrap"><table aria-label="${price?'Fiyat arbitrajı':'Funding çiftleri'}"><thead><tr><th></th><th>VARLIK</th><th>LONG / SHORT</th><th class="num">FUNDING / ${periodLabel()}</th>${col('spread')?'<th class="num">FİYAT FARKI</th>':''}${col('average')?'<th class="num">7G ORT. FARKI</th>':''}${col('fees')?'<th class="num">ÜCRET · 4 EMİR</th>':''}${col('net')?'<th class="num">NET GÖSTERGE¹</th>':''}${col('liquidity')?'<th class="num">HACİM / OI · USD</th>':''}${col('leverage')?'<th class="num">KALDIRAÇ</th>':''}${col('paid')?'<th class="num">ÖDENEN · 24S / 7G</th>':''}${col('interval')?'<th>ÖDEME ARALIĞI</th>':''}${col('trend')?'<th>SPREAD · 7G</th>':''}${col('risk')?'<th>PAPER DURUMU</th>':''}<th></th></tr></thead><tbody>${ps.map(p=>{const key=keyFor(p),net=netEstimate(p,price),avg=p.history?p.spread-p.history.mean:null;const deep=state.candidates.find(c=>c.asset===p.asset&&c.long===p.long&&c.short===p.short);return `<tr class="${hc.expanded===key?'selected':''}" tabindex="0" onclick="hcSet('expanded',hc.expanded==='${key}'?null:'${key}')" onkeydown="if(event.key==='Enter')hcSet('expanded','${key}')"><td><button class="fav ${hc.stars.has(key)?'on':''}" aria-label="${esc(p.asset+' '+name(p.long)+' '+name(p.short))} favori" onclick="event.stopPropagation();wideStar('${key}')">${hc.stars.has(key)?'★':'☆'}</button></td><td>${assetCell(p.asset).replace('PERP / PERP',p.pair_type==='spot-perp'?'SPOT / PERP':'PERP / PERP')}<div class="cell-sub">${p.pair_type==='spot-perp'?'SPOT → PERP':'PERP → PERP'}</div></td><td>${venueLeg(p.long,'L',p.long_price)}${venueLeg(p.short,'S',p.short_price)}<div class="cell-sub">${esc(p.long_price_type||'mark')} / ${esc(p.short_price_type||'mark')}</div></td><td class="num mono ${color(p.funding)}">${wrate(p.funding)}</td>${col('spread')?`<td class="num mono ${color(p.spread)}">${wpct(p.spread)}</td>`:''}${col('average')?`<td class="num mono ${color(avg)}">${wpct(avg)}</td>`:''}${col('fees')?`<td class="num mono">${p.fee_roundtrip==null?'—':money(hc.size*p.fee_roundtrip)}<div class="cell-sub">kayma hariç</div></td>`:''}${col('net')?`<td class="num mono ${color(net)}">${signedMoney(net)}<div class="cell-sub">${price?'7g ortalamaya dönüş':state.config.horizon+'s · sabit oran'}${hc.costs?'':' · ücret hariç'}</div></td>`:''}${col('liquidity')?`<td class="num mono">${money(p.min_volume)}<div class="cell-sub">OI ${money(p.min_oi)}</div></td>`:''}${col('leverage')?`<td class="num mono">${p.leverage?p.leverage+'x':'—'}</td>`:''}${col('paid')?`<td class="num mono">${wpct(p.paid24)}<div class="cell-sub">${wpct(p.paid7)}</div></td>`:''}${col('interval')?`<td class="mono">${intervalLabel(p.long_interval)} / ${intervalLabel(p.short_interval)}</td>`:''}${col('trend')?`<td>${spark(p.history?.points)}</td>`:''}${col('risk')?`<td><span class="tag ${deep?.eligible?'':'warn'}">${deep?(deep.eligible?'Funding adayı':'Bekle'):'Veri taraması'}</span></td>`:''}<td>▾</td></tr>${hc.expanded===key?wideDrawer(p):''}`}).join('')}</tbody></table>${ps.length?'':'<div class="empty"><h2>Bu koşullarda doğrulanmış çift yok</h2><p>Bağlantı kapsamını ve eksik veri durumlarını Borsalar ekranından görebilirsin.</p><button onclick="resetFilters()">Filtreleri temizle</button></div>'}</div><div class="toolbar"><span class="tooltip">¹ Gösterge hesabı. Gelecek funding, kayma, likidasyon ve stres kesin getirisi değildir. USD/USDT/USDC/USDG 1:1 varsayılır.</span>${hc.total>hc.limit?'<button onclick="hc.limit+=100;render()">100 çift daha göster ↓</button>':''}</div>`)};
function wideDrawer(p){const key=keyFor(p),q=hc.readJobs.quote,h=hc.readJobs.history,qr=q?.status==='done'&&q.result.asset===p.asset&&q.result.long===p.long&&q.result.short===p.short?q.result:null;return `<tr><td colspan="20" style="padding:0;white-space:normal"><div class="drawer"><div class="drawer-grid"><div><h2>${esc(p.asset)} · ${esc(name(p.long))} / ${esc(name(p.short))}</h2><p class="tooltip">${p.pair_type==='spot-perp'?'Spot long, perpetual short. Spot short/borç varsayılmaz.':'İki perpetual bacağı.'} Fiyat kaynakları: ${esc(p.long_price_type)} / ${esc(p.short_price_type)}.</p>${pairPriceCharts(p)}<button onclick="requestRead('history','${p.asset}','${p.long}','${p.short}','${p.long_kind}')" ${h?.status==='running'?'disabled':''}>${h?.status==='running'?'Geçmiş hazırlanıyor…':'7 günlük geçmişi ve funding’i getir'}</button><p class="tooltip">Geçmiş eksikse ileri doldurma yapılmaz. Oracle serileri perp uyum onayı almaz.</p></div><div>${line('Anlık fiyat farkı',wpct(p.spread))}${line('7 günlük ortalama',wpct(p.history?.mean))}${line('Sıfır çevresinde kesişim · 7g',p.history?.crossings??'Geçmişi getir')}${line('Gerçekleşmiş funding · 24s / 7g',wpct(p.paid24)+' / '+wpct(p.paid7))}${line('Ödeme aralıkları',intervalLabel(p.long_interval)+' / '+intervalLabel(p.short_interval))}${line('Bacak başına gösterge büyüklüğü',money(hc.size))}<p class="tooltip">${esc(p.reason||'Bu borsa çifti için otomatik paper yürütme henüz onaylı değil.')}</p><div class="filters"><button class="primary" onclick="requestRead('quote','${p.asset}','${p.long}','${p.short}','${p.long_kind}')" ${q?.status==='running'?'disabled':''}>${q?.status==='running'?'Defterler okunuyor…':'Dört emri defterle hesapla'}</button><button onclick="openWideBacktest('${p.asset}','${p.long}','${p.short}','${p.long_kind}')">Backtest ↗</button></div>${qr?`${line('Defterden giriş fiyat avantajı',money(qr.entry_capture))}${line('Dört emrin taker ücreti',money(qr.fees))}${line('Çıkış kayması vekili',money(qr.exit_drag_proxy))}${line('Sıfıra yakınsama net modeli',signedMoney(qr.convergence_net_model),color(qr.convergence_net_model))}<p class="tooltip">${esc(qr.method)}<br>${ts(qr.received)} · kayıtlar ${qr.audit_ids.join(', ')}</p>`:''}${[q,h].filter(j=>j?.status==='error').map(j=>`<div class="reason bad">${esc(j.error)}</div>`).join('')}</div></div></div></td></tr>`}
async function requestRead(kind,asset,long,short,long_kind){try{hc.readJobs[kind]={status:'running'};render();const resp=await fetch('/api/'+kind,{method:'POST',headers:{'Content-Type':'application/json','X-Paper-Token':window.paperToken},body:JSON.stringify({asset,long,short,long_kind,size:hc.size})});const r=await resp.json();if(!resp.ok)throw Error(r.error);pollReads(kind)}catch(e){hc.readJobs[kind]={status:'error',error:e.message};render()}}
async function pollReads(kind){try{const resp=await fetch('/api/read-jobs');if(!resp.ok)throw Error('Analiz bağlantısı yok');const jobs=await resp.json();hc.readJobs=jobs;if(jobs[kind]?.status==='running'){setTimeout(()=>pollReads(kind),1500);return}await refresh();render()}catch(e){hc.readJobs[kind]={status:'error',error:e.message};render()}}
function openWideBacktest(a,l,s,k){hc.btForm.long_kind=k;openBacktest(a,l,s)}
exchangeScreen=function(){const reg=viewData().registry||[],cov=viewData().coverage||{};return head('Borsalar ve bağlantı kapsamı','Tüm referans platformları burada listelenir. Katalog kaydı, çalışan public veri adaptörü ve paper yürütme ayrı durumlardır.')+`<div class="stat-grid">${[['Katalog',cov.total||63,'DEX + CEX'],['Public adaptör',cov.adapters||0,'Doğrulanan kod bağlantıları'],['Şu an erişilebilir',cov.available||0,(cov.cex||0)+' CEX · '+(cov.dex||0)+' DEX'],['Paper yürütme',state.wide_paper?state.wide_paper.venues.length:2,state.wide_paper?'Çoklu paper: veri gelen tüm borsalar · eski masa yalnızca Lighter RH–Extended':'Lighter RH ve Extended']].map(([l,n,t])=>`<div class="metric"><div class="label">${l}</div><div class="number">${n}</div><small>${t}</small></div>`).join('')}</div><div class="reason">Her platform bağlı değil. “Adaptör eksik” kayıtları fiyat tablosuna ve paper işlem havuzuna alınmaz. Erişim hatası, bölgesel engel ve eksik API alanları ayrıca gösterilir.</div><div class="table-wrap"><table aria-label="Borsa kapsamı"><thead><tr><th>BORSA</th><th>TÜR</th><th>PUBLIC VERİ</th><th>PAPER</th><th>AÇIKLAMA</th><th></th></tr></thead><tbody>${reg.map(r=>`<tr><td><b>${esc(r.label)}</b></td><td>${r.kind}</td><td><span class="tag ${r.fresh?'':'warn'}">${r.fresh?'Erişilebilir':r.status==='adapter_missing'?'Adaptör eksik':r.status==='unavailable'?'Bağlantı hatası':'Test / tarama bekleniyor'}</span></td><td>${r.paper?'Doğrulanmış model':'İşlem dışı'}</td><td style="white-space:normal;max-width:500px" class="tooltip">${esc(r.message||r.note)}</td><td>${r.fresh?`<button onclick="hc.venue='${r.id}';navigate('funding')">Piyasalar ↗</button>`:''}</td></tr>`).join('')}</tbody></table></div>`};
const baseWideRender=render;render=function(){if(state?.market_view?.registry){hcVenues=state.market_view.registry.map(v=>v.id);const strip=document.querySelector('.strip-left');if(strip){const info=strip.querySelector(':scope > span:nth-child(2)');if(info)info.textContent=state.config.symbols.length+' VARLIK / '+state.market_view.coverage.available+' ERİŞİLEBİLİR BORSA'}}baseWideRender();const form=document.getElementById('wide-filters');form?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);for(const k of ['minFunding','minSpread','minVsAvg','minVolume','minOi','minLeverage','minNet'])hc[k]=data.get(k);for(const k of ['sameInterval','paidPositive','oneAsset'])hc[k]=data.has(k);hc.limit=50;render()})};
hc.theme=localStorage.getItem('neutralbasis.theme')||'dark';document.documentElement.dataset.theme=hc.theme;
function toggleTheme(){hc.theme=hc.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=hc.theme;localStorage.setItem('neutralbasis.theme',hc.theme);render()}
const baseWideCommon=commonFilters;commonFilters=function(price){return baseWideCommon(price)+`<div class="filters"><button onclick="toggleTheme()">${hc.theme==='dark'?'☼ Açık tema':'☾ Koyu tema'}</button><label class="tooltip"><input type="checkbox" ${hc.alertOn?'checked':''} onchange="hc.alertOn=this.checked;hc.alertSeen=new Set(filteredPairs(tab==='price').map(keyFor));render()"> Panel açıkken yeni eşleşmeleri bildir</label><span class="tooltip">Bildirimler yalnızca bu panelde görünür; filtrelerini izler.</span></div>`};
const originalWideMatrix=fundingMatrix;fundingMatrix=function(){const original=hcVenues;try{const kinds=wideKinds();hcVenues=hcVenues.filter(v=>(hc.venueType==='all'||kinds[v]===hc.venueType)&&(hc.venue===v||viewData().registry?.find(r=>r.id===v)?.fresh));return originalWideMatrix()}finally{hcVenues=original}};
const finalWideRender=render;render=function(){if(hc.alertOn&&state&&['funding','price'].includes(tab)){const keys=new Set(filteredPairs(tab==='price').map(keyFor)),fresh=[...keys].filter(k=>hc.alertSeen&&!hc.alertSeen.has(k));if(fresh.length&&Date.now()-(hc.lastAlert||0)>300000){notice=fresh.length+' yeni filtre eşleşmesi: '+fresh.slice(0,3).map(k=>k.split(':')[0]).join(', ');hc.lastAlert=Date.now()}hc.alertSeen=keys}finalWideRender()};
function featureCoverage(){return `<div class="card" style="margin:18px 0"><div class="card-head"><h2>Özellik kapsamı · açık durum listesi</h2></div><div class="table-wrap"><table><tbody>${[['DEX/CEX katalog ve public tarama','63 kayıt; 30 kodlanmış adaptör. Bağlantı ve güncellik ayrıca doğrulanır.'],['Funding matrisi ve çift listesi','Aynı zaman tabanına normalize oranlar; yüzde/bp ve APR.'],['Spot–perp','Spot long / perp short taraması; spot short veya borç varsayılmaz.'],['Hacim, OI, kaldıraç ve maliyet filtreleri','Kaynakta doğrulanmış alanlar kullanılır; bilinmeyen değer seçili eşiği geçmez.'],['Gerçekleşmiş funding ve fiyat geçmişi','Seçili çift için isteğe bağlı indirilir. Tüm çiftlerin geçmişi otomatik hazır değildir.'],['Güncel defter maliyeti','Dört yönün VWAP’ı ve ücretleri. Gelecek çıkış için güncel defter vekili kullanılır.'],['Backtest','1/7/30/90 gün ve özel saat aralığı; borsa API kapsamıyla sınırlı. Aynı borsada spot–perp backtesti henüz yok.'],['Otomatik paper işlemler','Çoklu paper masası: veri gelen ve taker ücreti bilinen tüm borsalarda funding ve yakınsama stratejileri, tek ortak paper cüzdan. Eski masa: Lighter RH–Extended, 15 varlık. Gerçek emir yok.'],['Uyarılar','Panel açıkken yeni filtre eşleşmeleri. Telegram/e-posta veya kapalı panel bildirimi yok.'],['Henüz tamamlanmayanlar','33 platformun public adaptörü; tüm evrende otomatik geçmiş, funding istikrarı sıralaması, geniş paper yürütme ve tarihsel defter replay.']].map(([a,b])=>`<tr><td><b>${a}</b></td><td style="white-space:normal" class="tooltip">${b}</td></tr>`).join('')}</tbody></table></div></div>`}
const coverageExchangeScreen=exchangeScreen;exchangeScreen=function(){const html=coverageExchangeScreen();return html.replace('<div class="table-wrap"><table aria-label="Borsa kapsamı">',featureCoverage()+'<div class="table-wrap"><table aria-label="Borsa kapsamı">')};
const nativeAccountConnections=connections;connections=function(){return head('Borsa API bağlantıları','Public piyasa verisi için hesap anahtarı gerekmiyor. Kapsam, kimlik doğrulama ve paper yürütme ayrı doğrulamalardır.')+`<div class="card"><div class="card-head"><h2>Public kaynaklar · ${viewData().coverage?.adapters||0} adaptör / ${viewData().coverage?.total||63} platform</h2><button onclick="navigate('exchanges')">Tüm bağlantıları gör →</button></div><p class="tooltip" style="padding:18px">Yeni CEX/DEX kaynakları public API’lerinden okunur. Hesap anahtarı girilmesi bağlı olmayan bir platformu veya paper yürütme modelini otomatik hazır yapmaz. Bu sürümde hesap anahtarı doğrulaması Extended ile sınırlıdır; diğer platformların anahtarları toplanmaz.</p></div><details style="margin-top:20px"><summary style="padding:15px;border:1px solid var(--line);cursor:pointer">15 varlık listesi, mevcut beş native bağlantı ve Extended hesap ayarı</summary>${nativeAccountConnections()}</details>`};
render();

const convergenceReportsBase=performanceScreen;
performanceScreen=function(){const rows=state.closed.filter(p=>p.decision?.strategy==='convergence');return convergenceReportsBase()+`<div class="card"><div class="card-head"><h2>Eski masa · Yakınsama · yalnızca Lighter RH / Extended</h2></div><p class="tooltip" style="padding:16px">15 varlık taranır; iki borsadaki ortak piyasalar değerlendirilir. 7 günde ≥6 kesişim, ≥4 çift yönlü gün, en az asgari gün kadar (30 varsa 30) eşlenmiş geçmiş, korelasyon ve risk bütçesi gerekir. Giriş: fiyat avantajı − çıkış defteri vekili − dört emir ücreti − olası funding gideri − stres ≥ minimum net. Çıkış: fark ≤2 bp ve güncel defterden net ≥ minimum net; kayıp ve süre limitleri ayrıca geçerli. Gelecek çıkış likiditesi garanti değildir.</p><div class="table-wrap"><table><thead><tr><th>Varlık</th><th>Fiyat farkı PnL</th><th>Funding</th><th>Ücretler</th><th>Net</th><th>Durum / çıkış</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.asset)}</td><td>${signedMoney(p.price_pnl)}</td><td>${signedMoney(p.funding)}</td><td>${money(p.fees)}</td><td>${signedMoney(p.net)}</td><td>${p.pending_funding?.length?'Funding uzlaşması bekleniyor · ':''}${esc(p.close_reason)}</td></tr>`).join('')||'<tr><td colspan="6">Henüz kapanmış yakınsama işlemi yok. Kontrolleri geçmeyen fırsatta işlem açılmaz.</td></tr>'}</tbody></table></div><p class="tooltip" style="padding:16px">Net = fiyat PnL + funding − ücretler. Defter kayması ve ek slippage dolum fiyatlarına dahildir; ikinci kez düşülmez. CSV strateji ve bileşenleri ayrı içerir.</p></div>`};

function pairHistory(p){const job=hc.readJobs.history;return job?.status==='done'&&job.result.asset===p.asset&&job.result.long===p.long&&job.result.short===p.short&&(job.result.long_kind||'perp')===(p.long_kind||'perp')?job.result.history:p.history}
function paperChartEvents(p){if(p.long_kind==='spot')return [];const out=[];for(const pos of [...state.positions,...state.closed]){if(pos.asset!==p.asset||pos.legs?.length!==2)continue;const l=pos.legs.find(x=>x.venue===p.long),s=pos.legs.find(x=>x.venue===p.short);if(!l||!s)continue;
 if(l.entry>0&&s.entry>0)out.push({ts:Math.max(l.entered,s.entered),long_price:l.entry,short_price:s.entry,spread:Math.log(s.entry/l.entry)*100,label:'Paper açılış',color:'#38cf9d',id:pos.id});
 if(l.closed&&s.closed&&l.exit>0&&s.exit>0)out.push({ts:Math.max(l.exited,s.exited),long_price:l.exit,short_price:s.exit,spread:Math.log(s.exit/l.exit)*100,label:'Paper kapanış',color:'#f2b766',id:pos.id});}return out}
function pairChartSvg(points,fields,labels,colors,events,levels=[],unit='$'){
 if(!points?.length)return '<div class="plot-empty">Gerçek eşlenmiş fiyat geçmişi hazırlanmadı. Geçmişi getir düğmesini kullanın.</div>';
 const first=points[0].ts,last=Math.max(points[points.length-1].ts,...events.map(e=>e.ts)),visible=events.filter(e=>e.ts>=first&&e.ts<=last),values=[...points.flatMap(p=>fields.map(f=>p[f])),...visible.flatMap(p=>fields.map(f=>p[f])),...levels.map(l=>l.value)].filter(Number.isFinite);if(!values.length)return '<div class="plot-empty">İki fiyat serisi için geçmişi yenileyin.</div>';
 const min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.12,Math.abs(max)*.00001,1e-8),lo=min-pad,hi=max+pad,X=t=>48+(t-first)/(last-first||1)*830,Y=v=>220-(v-lo)/(hi-lo)*196,fmt=v=>unit==='%'?v.toFixed(3)+'%':v.toLocaleString('en-US',{maximumFractionDigits:v<1?6:2}),date=t=>new Date(t*1000).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'});
 const svg=`<svg class="plot" viewBox="0 0 1000 260" role="img" aria-label="${esc(labels.join(' / '))}">${[0,.25,.5,.75,1].map(f=>`<line class="chart-gridline" x1="48" x2="878" y1="${24+196*f}" y2="${24+196*f}"/><text x="890" y="${28+196*f}">${esc(fmt(hi-(hi-lo)*f))}</text>`).join('')}${levels.map(l=>`<line x1="48" x2="878" y1="${Y(l.value)}" y2="${Y(l.value)}" stroke="${l.color}" stroke-dasharray="5 5"><title>${esc(l.label)}: ${fmt(l.value)}</title></line>`).join('')}${fields.map((f,i)=>`<polyline fill="none" stroke="${colors[i]}" stroke-width="2" points="${points.map(p=>X(p.ts).toFixed(2)+','+Y(p[f]).toFixed(2)).join(' ')}"/>${points.map(p=>`<circle cx="${X(p.ts)}" cy="${Y(p[f])}" r="4" fill="transparent"><title>${esc(labels[i])} · ${date(p.ts)} · ${fmt(p[f])}</title></circle>`).join('')}`).join('')}${visible.map(e=>`<line x1="${X(e.ts)}" x2="${X(e.ts)}" y1="24" y2="220" stroke="${e.color}" stroke-dasharray="2 4"/>${fields.map(f=>`<circle cx="${X(e.ts)}" cy="${Y(e[f])}" r="5" fill="${e.color}" stroke="#101411"><title>${esc(e.label)} · ${date(e.ts)} · ${fmt(e[f])} · ${esc(e.id)}</title></circle>`).join('')}`).join('')}<text x="48" y="250">${esc(date(first))}</text><text x="640" y="250">${esc(date(last))}</text></svg>`;
 return `<div class="plot-wrap"><div class="legend">${labels.map((l,i)=>`<span><i style="background:${colors[i]}"></i>${esc(l)}</span>`).join('')}${levels.map(l=>`<span><i style="background:${l.color}"></i>${esc(l.label)} ${fmt(l.value)}</span>`).join('')}${visible.length?'<span>● Paper açılış / kapanış</span>':''}</div>${svg}</div>`
}
function pairPriceCharts(p){const h=pairHistory(p),points=h?.points?.filter(x=>Number.isFinite(x.long_price)&&Number.isFinite(x.short_price)),events=paperChartEvents(p),levels=h?[{value:0,label:'Sıfır',color:'#59635b'},{value:h.mean*100,label:'7g ortalama',color:'#ac9be6'},{value:Math.max(.0005,h.mean+h.sd)*100,label:'Giriş sinyali ≥',color:'#e3b86e'},{value:.02,label:'Çıkış sinyali ≤',color:'#63c8b4'}]:[];return `<div class="pair-price-charts"><h3>İki borsada fiyat hareketi · 7 gün</h3>${pairChartSvg(points,['long_price','short_price'],[name(p.long),name(p.short)],['#58b9ed','#eda575'],events)}<h3>Fiyat farkı ve yakınsama eşikleri</h3>${pairChartSvg(points?.map(x=>({...x,spread:x.spread*100})),['spread'],['log(Short / Long) · %'],['#a8c697'],events,levels,'%')}<p class="tooltip">Gerçek eşlenmiş 1 saatlik işlem kapanışları · UTC+3. Noktanın üzerine gelince zaman ve fiyat görünür. Kesikli çizgiler sinyal eşikleridir; giriş için masraf ve risk onayı, çıkış için net kazanç koşulu ayrıca aranır. Eşikler Lighter RH–Extended yakınsama modelini referans alır. ${events.length?'İşaretler gerçek paper dolum zaman ve fiyatlarıdır; saatlik mumlardan türetilmez.':'Bu çift için kayıtlı paper açılış/kapanış işareti yok.'}</p></div>`}
const priceChartsHcSet=hcSet;hcSet=function(k,v){priceChartsHcSet(k,v);if(k==='expanded'&&v){const p=filteredPairs(tab==='price').find(p=>keyFor(p)===v);if(p&&!pairHistory(p)?.points?.[0]?.long_price&&hc.readJobs.history?.status!=='running')requestRead('history',p.asset,p.long,p.short,p.long_kind||'perp')}};

// Multi-venue paper desk: the best funding pair across every scanned venue, one pooled paper wallet.
const wideFields=[['wide_capital','Sermaye $',10,1000000,1],['wide_size','Azami büyüklük $',10,100000,1],['wide_leverage','Kaldıraç',1,10,0.5],['wide_max_positions','Azami pozisyon',1,10,1],['wide_horizon','Horizon saat',1,168,1],['wide_min_net','Asgari net $',0,1000,0.05],['wide_risk','Pozisyon kayıp limiti $',0.01,10000,0.5],['wide_daily_loss','Günlük kayıp limiti $',0.01,100000,1],['wide_min_corr','Asgari korelasyon',0.5,1,0.01],['wide_max_z','Azami z-score',0.5,10,0.1],['wide_lock_trail','Kâr kilidi: geri verilen pay',0.1,0.9,0.05],['wide_conv_leverage','Yakınsama kaldıracı',1,10,0.5],['wide_conv_min_cross_7','7g asgari kesişim',1,168,1],['wide_conv_min_cross_30','30g asgari kesişim',1,720,1],['wide_min_history_days','Asgari geçmiş gün (30 varsa 30 kullanılır)',7,30,1],['wide_conv_max_hold_hours','Yakınsama azami saat',1,720,1],['wide_conv_exit_bps','Kapanış makası bp',0,50,0.5],['wide_max_spread_sd_bps','Funding: azami fark sd bp',1,500,1],['wide_weak_minutes','Zayıflık onay süresi dk',0,1440,5]];
const stratLabel=x=>x==='convergence'?'Yakınsama':'Funding';
function multiScreen(){const w=state.wide_paper;if(!w)return head('Çoklu borsa paper','Çoklu borsa masası bu motorda yok.');const c=w.config,b=w.balance,bp=x=>x==null?'—':(x*10000).toFixed(2)+' bp';
 const pos=w.positions.map(p=>{const l=p.legs.find(x=>x.side==='long'),s=p.legs.find(x=>x.side==='short');return `<tr><td><b>${esc(p.asset)}</b> <small class="muted">${stratLabel(p.strategy)}</small></td><td>${l?esc(name(l.venue)):'—'}</td><td>${s?esc(name(s.venue)):'—'}</td><td>${money(p.decision.size)}</td><td class="${color(p.funding)}">${signedMoney(p.funding)}</td><td>${money(p.fees)}</td><td class="${color(p.net_if_closed)}">${signedMoney(p.net_if_closed)}</td><td>${esc(p.status)}${p.pending_funding?.length?' <small class="muted">funding bekliyor</small>':''}</td><td><button onclick="action('close',{id:'${p.id}'})">Kapat</button></td></tr>`}).join('')||'<tr><td colspan="9" class="muted">Açık çoklu borsa pozisyonu yok.</td></tr>';
 const cands=w.candidates.slice(0,25).map(x=>{const d=w.assessed.find(a=>a.asset===x.asset&&a.long===x.long&&a.short===x.short);return `<tr><td>${x.rank}</td><td><b>${esc(x.asset)}</b></td><td>${esc(name(x.long))} <small class="muted">${intervalLabel(x.interval_long)}</small></td><td>${esc(name(x.short))} <small class="muted">${intervalLabel(x.interval_short)}</small></td><td>${bp(x.funding_horizon)}</td><td>${bp(x.fee_roundtrip)}</td><td class="${color(x.score)}">${bp(x.score)}</td><td>${bp(x.spread)}</td><td>${d?(d.eligible?`<span class="good">Uygun · ${signedMoney(d.net)}</span>`:esc((d.reasons||[])[0]||'')):'<span class="muted">—</span>'}</td></tr>`}).join('')||'<tr><td colspan="9" class="muted">Pozitif funding farkı olan çift yok ya da tarama henüz bitmedi.</td></tr>';
 const convs=(w.conv_candidates||[]).slice(0,25).map(x=>{const d=w.assessed.find(a=>a.strategy==='convergence'&&a.asset===x.asset&&a.long===x.long&&a.short===x.short),h=d?.convergence_history;return `<tr><td>${x.rank}</td><td><b>${esc(x.asset)}</b></td><td>${esc(name(x.long))}</td><td>${esc(name(x.short))}</td><td>${bp(x.spread)}</td><td>${bp(x.fee_roundtrip)}</td><td class="${color(x.score)}">${bp(x.score)}</td><td>${h?`${h.cross7} / ${h.cross30}`:'—'}</td><td>${h?.avg_close_hours!=null?h.avg_close_hours.toFixed(1)+' s':'—'}</td><td>${d?(d.eligible?`<span class="good">Uygun · ${signedMoney(d.net)}</span>`:esc((d.reasons||[])[0]||'')):'<span class="muted">—</span>'}</td></tr>`}).join('')||'<tr><td colspan="10" class="muted">Ücret sonrası pozitif fiyat boşluğu olan çift yok.</td></tr>';
 const rep=w.report||{},repRow=(k,label)=>{const r=rep[k]||{};return `<tr><td><b>${label}</b></td><td>${r.open??0}</td><td>${r.trades??0}</td><td>${r.wins??0}/${r.settled??0}</td><td class="${color(r.price_pnl)}">${signedMoney(r.price_pnl)}</td><td class="${color(r.funding)}">${signedMoney(r.funding)}</td><td>${money(r.fees)}</td><td class="${color(r.net)}">${signedMoney(r.net)}</td><td>${r.unverified_payments??0} / ${r.pending??0}</td></tr>`};
 const done=w.closed.slice(-20).reverse().map(p=>{const l=p.legs.find(x=>x.side==='long'),s=p.legs.find(x=>x.side==='short');return `<tr><td><b>${esc(p.asset)}</b> <small class="muted">${stratLabel(p.strategy)}</small></td><td>${l?esc(name(l.venue)):'—'}</td><td>${s?esc(name(s.venue)):'—'}</td><td class="${color(p.funding)}">${signedMoney(p.funding)}</td><td>${money(p.fees)}</td><td class="${color(p.net)}">${signedMoney(p.net)}</td><td>${esc(p.close_reason||'')}${p.entry_reason?`<br><small class="muted">${esc(p.entry_reason)}</small>`:''}</td></tr>`}).join('')||'<tr><td colspan="7" class="muted">Kapanmış işlem yok.</td></tr>';
 return head('Çoklu borsa paper',esc(w.method))+`<div class="card"><div class="card-head"><h2>Cüzdan · ${w.venues.length} borsa verisi · ${w.candidate_count} çift</h2></div><div class="table-wrap"><table><tbody><tr><td>Nakit</td><td>${money(b.cash)}</td><td>Özsermaye</td><td>${money(b.equity)}</td><td>Kullanılan marjin</td><td>${money(b.margin)}</td><td>Bugün</td><td class="${color(w.daily_pnl)}">${signedMoney(w.daily_pnl)}</td></tr></tbody></table></div>${w.error?`<p class="bad">${esc(w.error)}</p>`:''}</div>`
 +`<div class="card"><div class="card-head"><h2>Strateji sonuçları · net = fiyat PnL + funding − komisyon</h2></div><div class="table-wrap"><table><thead><tr><th>Strateji</th><th>Açık</th><th>İşlem</th><th>Kârlı</th><th>Fiyat PnL</th><th>Funding</th><th>Komisyon</th><th>Net</th><th>Doğrulanmamış / bekleyen</th></tr></thead><tbody>${repRow('funding','Funding')}${repRow('convergence','Yakınsama')}</tbody></table></div></div>`+`<div class="card"><div class="card-head"><h2>Açık pozisyonlar</h2></div><div class="table-wrap"><table><thead><tr><th>Varlık</th><th>Long</th><th>Short</th><th>Büyüklük</th><th>Funding</th><th>Ücret</th><th>Kapatılırsa net</th><th>Durum</th><th></th></tr></thead><tbody>${pos}</tbody></table></div></div>`
 +`<div class="card"><div class="card-head"><h2>Funding fırsatları · ${c.wide_horizon}s horizon</h2></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Varlık</th><th>Long</th><th>Short</th><th>Funding</th><th>4 ücret</th><th>Skor</th><th>Fiyat farkı</th><th>Derin kontrol</th></tr></thead><tbody>${cands}</tbody></table></div></div>`
 +`<div class="card"><div class="card-head"><h2>Yakınsama fırsatları · ucuzda long, pahalıda short</h2></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Varlık</th><th>Long</th><th>Short</th><th>Fiyat farkı</th><th>4 ücret</th><th>Skor</th><th>Kesişim 7g / uzun</th><th>Ort. kapanma</th><th>Derin kontrol</th></tr></thead><tbody>${convs}</tbody></table></div></div>`+`<div class="card"><div class="card-head"><h2>Kapanmış işlemler</h2></div><div class="table-wrap"><table><thead><tr><th>Varlık</th><th>Long</th><th>Short</th><th>Funding</th><th>Ücret</th><th>Net</th><th>Neden</th></tr></thead><tbody>${done}</tbody></table></div></div>`
 +`<div class="card"><div class="card-head"><h2>Ayarlar</h2></div><form id="wide-config-form" class="formgrid">${wideFields.map(([k,l,min,max,step])=>`<label>${l}<input type="number" name="${k}" value="${c[k]}" min="${min}" max="${max}" step="${step}" required ${k==='wide_capital'&&(w.positions.length||w.closed.length)?'disabled':''}></label>`).join('')}<label><input type="checkbox" name="wide_enabled" ${c.wide_enabled?'checked':''}> Yeni girişler açık</label><label><input type="checkbox" name="wide_funding_enabled" ${c.wide_funding_enabled?'checked':''}> Funding stratejisi</label><label><input type="checkbox" name="wide_conv_enabled" ${c.wide_conv_enabled?'checked':''}> Yakınsama stratejisi</label><div class="wide"><button type="submit" class="primary">Kaydet</button></div></form></div>`}
const multiBaseRender=render;render=function(){multiBaseRender();if(tab!=='multi'||!state?.config)return;const scroll=window.scrollY;app.innerHTML=multiScreen();window.scrollTo(0,scroll);document.title='neutralbasis — Çoklu borsa paper';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===tab));
 document.getElementById('wide-config-form')?.addEventListener('submit',e=>{e.preventDefault();const body={};for(const input of e.target.querySelectorAll('input')){if(input.disabled)continue;body[input.name]=input.type==='checkbox'?input.checked:Number(input.value)}action('config',body)})};

// Performans: the all-venue desk's per-strategy results first, so the old two-venue cards are not mistaken for it.
const multiReportsBase=performanceScreen;performanceScreen=function(){const html=multiReportsBase(),w=state.wide_paper;if(!w)return html;const rep=w.report||{},row=(k,label)=>{const r=rep[k]||{};return `<tr><td><b>${label}</b></td><td>${r.open??0}</td><td>${r.trades??0}</td><td>${r.wins??0}/${r.settled??0}</td><td class="${color(r.net)}">${signedMoney(r.net)}</td></tr>`};const card=`<div class="card"><div class="card-head"><h2>Çoklu borsa masası · tüm borsalar</h2><a href="#multi">Çoklu paper sekmesi →</a></div><div class="table-wrap"><table><thead><tr><th>Strateji</th><th>Açık</th><th>İşlem</th><th>Kârlı</th><th>Net</th></tr></thead><tbody>${row('funding','Funding')}${row('convergence','Yakınsama')}</tbody></table></div><p class="tooltip" style="padding:0 16px 16px">Aşağıdaki kartlar eski Lighter RH / Extended masasına aittir. Tüm borsalardaki funding ve yakınsama işlemleri Çoklu paper sekmesindedir.</p></div>`;const i=html.indexOf('<div class="card"');return i<0?html+card:html.slice(0,i)+card+html.slice(i)};
// Background history keeper: how many markets already have stored 30-day history.
const historyStatusRender=render;render=function(){historyStatusRender();const h=state?.history_status,strip=document.querySelector('.strip-left');if(!h||!strip)return;let el=document.getElementById('history-status');if(!el){el=document.createElement('span');el.id='history-status';strip.appendChild(el)}el.textContent=`GEÇMİŞ ${h.synced}/${h.markets??'?'} PİYASA${h.failed?` · ${h.failed} HATA`:''}`;el.title='Fiyat ve funding geçmişi arka planda çekilir, SQLite’a kaydedilir; yeniden başlatmada yalnızca yeni mumlar alınır.'};

// Funding matrix like the reference: every listed perp on every reachable venue, in the display period.
// Max spread = short at the highest rate, long at the lowest, within the pair filter.
// Net 7g = realized stored payments over the last 7 days for that pair, minus 4 fills when costs are on.
hc.view='matrix';Object.assign(hc,{mxPair:'dex',mxYield:'all',mxQuery:'',mxLimit:50,mxSort:'spread',mxLiq:'1m'});
let mxData=null,mxLoading=false,mxError='',mxTried=0,mxMemo=null;
async function loadMatrix(){const t=Date.now()/1000;if(mxLoading||t-mxTried<15||mxData&&t-mxData.ts<60)return;mxLoading=true;mxTried=t;try{const r=await fetch('/api/funding-matrix');if(!r.ok)throw Error('Matris verisi alınamadı');mxData=await r.json();mxError='';mxMemo=null}catch(e){mxError=e.message}finally{mxLoading=false;if(tab==='home'||tab==='funding'&&hc.view==='matrix')render()}}
// Liquidity gate like the reference's "liquid pairs": a leg counts when its open interest, or its
// 24h volume where OI is not published, reaches the floor. Native-feed venues publish neither
// (selected majors only) and pass. Marks more than 15% apart are two tokens sharing a ticker.
const liqFloors={all:0,'1m':1e6,'10m':1e7};
function legLiquid(d,v,c,floor){if(!floor)return true;if(c[6]!=null)return c[6]>=floor;if(c[5]!=null)return c[5]>=floor;return !!d.venues.find(x=>x.id===v)?.curated}
const samePrice=(A,B)=>!A[4]||!B[4]||Math.abs(Math.log(B[4]/A[4]))<=0.15;
const usdShort=x=>x==null?'—':'$'+(x>=1e9?(x/1e9).toFixed(2)+'B':x>=1e6?(x/1e6).toFixed(1)+'M':x>=1e3?(x/1e3).toFixed(0)+'K':Math.round(x));
function mxPairOk(kinds,l,s){const k=[kinds[l],kinds[s]];return hc.mxPair==='any'||(hc.mxPair==='dex'?k.includes('DEX'):hc.mxPair==='dexonly'?k.every(x=>x==='DEX'):k.every(x=>x==='CEX'))}
function mxRows(){const d=mxData,kinds=Object.fromEntries(d.venues.map(v=>[v.id,v.kind])),key=[d.ts,hc.mxPair,hc.costs,hc.size,hc.venueType,hc.venue,hc.mxLiq].join('|');if(mxMemo?.key===key)return mxMemo.rows;
 const floor=liqFloors[hc.mxLiq]||0,rows=[];for(const x of d.assets){const vs=Object.keys(x.cells).filter(v=>(hc.venueType==='all'||kinds[v]===hc.venueType)&&legLiquid(d,v,x.cells[v],floor));let best=null;
  for(const l of vs)for(const s of vs){if(l===s||(hc.venue!=='all'&&![l,s].includes(hc.venue))||!mxPairOk(kinds,l,s)||!samePrice(x.cells[l],x.cells[s]))continue;const g=x.cells[s][0]-x.cells[l][0];if(g>0&&(!best||g>best.spread))best={long:l,short:s,spread:g}}
  let net7=null;if(best){const L=x.cells[best.long],S=x.cells[best.short];if(L[3]!=null&&S[3]!=null){const fee=hc.costs?(L[2]!=null&&S[2]!=null?2*(L[2]+S[2]):null):0;if(fee!=null)net7=hc.size*(S[3]-L[3]-fee)}}
  rows.push({asset:x.asset,cells:x.cells,...(best||{}),spread:best?best.spread:null,net7})}
 mxMemo={key,rows};return rows}
function mxSet(k,v){hc[k]=v;if(k!=='mxLimit')hc.mxLimit=50;render()}
function mxQuery(input){const pos=input.selectionStart;hc.mxQuery=input.value;hc.mxLimit=50;render();const next=document.getElementById('mx-search');if(next){next.focus();next.setSelectionRange(pos,pos)}}
fundingMatrix=function(){loadMatrix();if(!mxData)return `<div class="plot-empty">${mxError?esc(mxError)+' · 15 sn içinde yeniden denenecek':'Funding matrisi yükleniyor…'}</div>`;
 const kinds=Object.fromEntries(mxData.venues.map(v=>[v.id,v.kind])),q=hc.mxQuery.trim().toUpperCase();
 let rows=mxRows().filter(r=>(!q||r.asset.toUpperCase().includes(q))&&(hc.mxYield==='all'||(hc.mxYield==='steady'?r.net7>0:r.spread!=null&&r.spread*8>=0.001)));
 rows.sort((a,b)=>hc.mxSort==='net'?(b.net7??-Infinity)-(a.net7??-Infinity):(b.spread??-Infinity)-(a.spread??-Infinity));
 const total=rows.length,shown=rows.slice(0,hc.mxLimit),cols=mxData.venues.filter(v=>(hc.venueType==='all'||v.kind===hc.venueType)&&(hc.venue==='all'||v.id===hc.venue||shown.some(r=>r.long===v.id||r.short===v.id)));
 const seg=(k,opts)=>`<div class="segmented">${opts.map(([v,l])=>`<button class="${hc[k]===v?'active':''}" onclick="mxSet('${k}','${v}')">${l}</button>`).join('')}</div>`;
 const cell=(r,v)=>{const c=r.cells[v];if(!c)return '<td class="num muted">—</td>';const side=v===r.long?'long':v===r.short?'short':'';return `<td class="num mono ${c[0]<0?'rate-neg':'rate-pos'}" style="${side?'box-shadow:inset 0 0 0 1px '+(side==='long'?'#42c68e':'#eb778a'):''}">${rate(c[0])}<div class="cell-sub">${intervalLabel(c[1])}${side?' · '+(side==='long'?'LONG':'SHORT'):''}</div></td>`};
 return `<div class="toolbar"><div class="toolbar-left"><input id="mx-search" class="search" aria-label="Varlık ara" placeholder="Varlık ara" value="${esc(hc.mxQuery)}" oninput="mxQuery(this)">${seg('mxPair',[['dex','DEX içeren'],['dexonly','Yalnız DEX'],['cexonly','Yalnız CEX'],['any','Hepsi']])}${seg('mxYield',[['all','Tümü'],['steady','İstikrarlı'],['high','Yüksek getiri']])}${seg('mxSort',[['spread','Fark sırası'],['net','Net 7g sırası']])}${seg('mxLiq',[['all','Likidite: hepsi'],['1m','≥ $1M'],['10m','≥ $10M']])}</div><span class="screener-count">${mxData.assets.length.toLocaleString()} varlık · ${mxData.venues.length} borsa · ${total.toLocaleString()} eşleşme, ilk ${shown.length}</span></div>`
 +`<div class="table-wrap"><table class="matrix" aria-label="Funding matrisi"><thead><tr><th>VARLIK</th><th class="num">EN GENİŞ FARK · ${periodLabel()}</th><th class="num">NET SON 7G · ${money(hc.size)}</th>${cols.map(v=>`<th class="num">${esc(v.label)}<div class="cell-sub">${v.kind} · ${v.assets}</div></th>`).join('')}</tr></thead><tbody>${shown.map(r=>`<tr><td><b>${esc(r.asset)}</b>${r.long?`<div class="cell-sub">L ${esc(name(r.long))} / S ${esc(name(r.short))}</div>`:''}</td><td class="num mono good">${r.spread==null?'—':rate(r.spread)}</td><td class="num mono ${color(r.net7)}">${r.net7==null?'<span class="muted" title="7 günlük ödeme geçmişi henüz tam değil">geçmiş eksik</span>':signedMoney(r.net7)}</td>${cols.map(v=>cell(r,v.id)).join('')}</tr>`).join('')}</tbody></table></div>`
 +`<div class="table-foot">${total>shown.length?`<button onclick="mxSet('mxLimit',${hc.mxLimit+100})">100 daha göster</button> `:''}Oranlar ${periodLabel()} bazında. İstikrarlı: son 7 gün gerçekleşen funding ücret sonrası pozitif. Yüksek getiri: fark ≥ %0,1 / 8s. Likidite: her bacakta OI (yayımlanmıyorsa 24s hacim) eşiği; seçili varlıklardaki yerel DEX beslemeleri geçer, fiyatları %15'ten fazla ayrışan bacaklar farklı token sayılır. Net 7g yalnızca 7 günlük ödemeler tam kayıtlıysa gösterilir; seçili olmayan varlıklarda funding geçmişi en geniş farklı ilk 40 varlık için, fiyat ve funding geçmişi paper adaylarının bacakları için öncelikle arka planda doldurulur.</div>`+mxCoverage()};
// Scanned venues that are missing from the matrix, or limited to the selected assets, with the reason.
function mxCoverage(){const c=mxData.coverage||[];if(!c.length)return '';return `<details class="card" style="margin-top:12px" ${hc.mxCov?'open':''} ontoggle="hc.mxCov=this.open"><summary>Matriste olmayan ya da sınırlı borsalar (${c.length})</summary><div class="table-wrap"><table><thead><tr><th>BORSA</th><th>TÜR</th><th class="num">VARLIK</th><th>NEDEN</th></tr></thead><tbody>${c.map(x=>`<tr><td><b>${esc(x.label)}</b></td><td>${x.kind}</td><td class="num">${x.assets||'—'}</td><td style="white-space:normal">${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div></details>`}

// Home overview like the reference landing: computed only from data this desk actually has.
let homeMemo=null;
// Best pairs follow the reference: at least one DEX leg, both legs liquid (OI ≥ $1M, or 24h volume
// where OI is unpublished) and priced as the same token; extreme rates need OI ≥ $2M.
const HOME_PAIR_FLOOR=1e6,HOME_EXTREME_FLOOR=2e6;
function homeStats(){const d=mxData,key=[d.ts,hc.size,hc.costs].join('|');if(homeMemo?.key===key)return homeMemo;const kinds=Object.fromEntries(d.venues.map(v=>[v.id,v.kind]));let paidPairs=0,paidWins=0;const best=[],cells=[];
 for(const x of d.assets){const all=Object.keys(x.cells),vs=all.filter(v=>legLiquid(d,v,x.cells[v],HOME_PAIR_FLOOR));for(const v of all)if(legLiquid(d,v,x.cells[v],HOME_EXTREME_FLOOR))cells.push({asset:x.asset,venue:v,rate:x.cells[v][0],interval:x.cells[v][1],oi:x.cells[v][6],volume:x.cells[v][5]});
  for(let i=0;i<vs.length;i++)for(let j=i+1;j<vs.length;j++){const A=x.cells[vs[i]],B=x.cells[vs[j]];if(A[3]==null||B[3]==null||!samePrice(A,B))continue;const fee=hc.costs?(A[2]!=null&&B[2]!=null?2*(A[2]+B[2]):null):0;if(fee==null)continue;paidPairs++;if(hc.size*(Math.abs(A[3]-B[3])-fee)>0)paidWins++}
  let top=null;for(const l of vs)for(const s of vs){if(l===s||(kinds[l]!=='DEX'&&kinds[s]!=='DEX')||!samePrice(x.cells[l],x.cells[s]))continue;const g=x.cells[s][0]-x.cells[l][0];if(g>0&&(!top||g>top.spread))top={asset:x.asset,long:l,short:s,spread:g}}if(top)best.push(top)}
 best.sort((a,b)=>b.spread-a.spread);cells.sort((a,b)=>Math.abs(b.rate)-Math.abs(a.rate));
 const btc=Object.entries(d.assets.find(x=>x.asset==='BTC')?.cells||{}),avg=k=>{const r=btc.filter(([v])=>kinds[v]===k).map(([,c])=>c[0]);return r.length?r.reduce((a,b)=>a+b,0)/r.length:null},top=btc.filter(([v])=>kinds[v]==='DEX').sort((a,b)=>b[1][0]-a[1][0])[0];
 homeMemo={key,paidPairs,paidWins,best,cells,btcDex:avg('DEX'),btcCex:avg('CEX'),btcTop:top};return homeMemo}
const legs=(l,s)=>`<span class="good">LONG</span> ${esc(name(l))} &nbsp; <span class="bad">SHORT</span> ${esc(name(s))}`;
function homeCard(title,sub,link,cols,rows,empty){return `<div class="card" style="margin:0"><div class="card-head"><h2>${title} <small class="muted">${sub}</small></h2>${link?`<a href="#${link[0]}">${link[1]} →</a>`:''}</div><div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th${c.startsWith('#')?' class="num"':''}>${c.replace('#','')}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${cols.length}" class="muted">${empty}</td></tr>`}</tbody></table></div></div>`}
function homeScreen(){loadMatrix();const d=mxData;if(!d)return head('Perp borsa takibi','Funding matrisi yükleniyor…')+`<div class="plot-empty">${mxError?esc(mxError):'Veriler hazırlanıyor…'}</div>`;
 const h=homeStats(),prices=(state.market_view?.pairs||[]).filter(p=>p.pair_type==='perp-perp'),priced=prices.filter(p=>p.history),priceWins=priced.filter(p=>(netEstimate(p,true)??-1)>0).length,w=state.wide_paper,time=new Date(d.ts*1000).toLocaleTimeString('tr-TR',{timeZone:'Europe/Istanbul',hour:'2-digit',minute:'2-digit'});
 const tiles=[[`BTC funding · DEX ortalaması /${periodLabel()}`,rate(h.btcDex),`CEX ${rate(h.btcCex)}${h.btcTop?' · en yüksek '+esc(name(h.btcTop[0]))+' '+rate(h.btcTop[1][0]):''}`],[`Kârda funding çiftleri · ${money(hc.size)}`,h.paidWins.toLocaleString(),`${h.paidPairs.toLocaleString()} likit çiftten, son 7 gün gerçekleşen, ücret sonrası`],[`Kârda fiyat farkları · ${money(hc.size)}`,priceWins.toLocaleString(),`${priced.length.toLocaleString()} çiftten, fark 7g ortalamasına dönerse`],['Kapsam',d.assets.length.toLocaleString(),`varlık · ${d.venues.length} borsa (${d.venues.filter(v=>v.kind==='DEX').length} DEX)`],...(w?[['Çoklu paper özsermaye',money(w.balance.equity),`${w.positions.length} açık pozisyon · ${w.closed.length} kapanan`]]:[])];
 const best=h.best.slice(0,8).map(p=>`<tr><td><b>${esc(p.asset)}</b></td><td>${legs(p.long,p.short)}</td><td class="num mono good">${rate(p.spread)}</td><td class="num mono good">+${(p.spread*8760*100).toFixed(1)}%</td></tr>`);
 const spreads=d.assets.filter(x=>x.price_spread!=null).sort((a,b)=>b.price_spread-a.price_spread).slice(0,8).map(x=>`<tr><td><b>${esc(x.asset)}</b></td><td>${legs(x.price_long,x.price_short)}</td><td class="num mono">${pct(x.price_spread)}</td></tr>`);
 const extreme=h.cells.slice(0,8).map(c=>`<tr><td><b>${esc(c.asset)}</b></td><td>${esc(name(c.venue))} <small class="muted">${intervalLabel(c.interval)}</small></td><td class="num mono ${c.rate<0?'bad':'good'}">${rate(c.rate)}</td><td class="num mono">${c.oi!=null?usdShort(c.oi):c.volume!=null?'<span title="OI yayımlanmıyor; 24s hacim">'+usdShort(c.volume)+' hcm</span>':'<span class="muted" title="Yerel DEX beslemesi">—</span>'}</td></tr>`);
 const listings=(d.listings||[]).slice(0,8).map(x=>`<tr><td><b>${esc(x.asset)}</b></td><td>${x.venues.slice(0,3).map(v=>esc(name(v))).join(', ')}${x.venues.length>3?' +'+(x.venues.length-3):''}</td><td class="num">${x.venues.length}</td><td class="num mono">${new Date(x.ts*1000).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</td></tr>`);
 return head('Perp borsa takibi',`${d.venues.length} borsa · veri ${time} · public veri, tavsiye değildir`)+`<div class="stat-grid" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr))">${tiles.map(([l,n,t])=>`<div class="metric"><div class="label">${l}</div><div class="number">${n}</div><small>${t}</small></div>`).join('')}</div>`
 +`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,460px),1fr));gap:18px">`
 +homeCard('En iyi funding çiftleri','en az bir DEX bacağı · OI ≥ $1M',['funding','Tüm çiftler'],['Varlık','Bacaklar','#Fark /'+periodLabel(),'#APR'],best,'Henüz iki borsada oranı olan varlık yok.')
 +homeCard('En geniş fiyat farkları','tüm varlıklar · mark fiyatı',['price','Tüm çiftler'],['Varlık','Bacaklar','#Fark'],spreads,'Fiyat verisi bekleniyor.')
 +homeCard('Uç funding','tek piyasa, OI ≥ $2M',['funding','Tüm oranlar'],['Varlık','Borsa','#Oran /'+periodLabel(),'#OI'],extreme,'Oran verisi bekleniyor.')
 +homeCard('Yeni listelemeler','son 7 gün, takip başladıktan sonra',null,['Varlık','Borsalar','#Sayı','#İlk görülme'],listings,'Takip başladı; bundan sonra yeni listelenen perp’ler burada görünür.')
 +`</div>`}
const homeBaseRender=render;render=function(){homeBaseRender();if(tab!=='home'||!state?.config)return;const scroll=window.scrollY;app.innerHTML=homeScreen();window.scrollTo(0,scroll);document.title='neutralbasis — Özet';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===tab))};
